interface InteractiveChartTooltipActionItemProps extends WithChildren {
  /** Callback function action is triggered / selected. */
  onSelect: () => void;
}

/**
 * Defines slots into which children of this item should be rendered. There
 * are two special slots for the tooltip and the icon. Everything else will be
 * rendered into the freeform slot.
 */
type ItemSlots = {
  tooltip: ReactNode | null;
  icon: ReactNode | null;
  freeform: ReactNode[];
};

